export const SCHOOL='โรงเรียนสามัคคีศรีวิชัย';
export const ROLES={admin:'ผู้ดูแลระบบ',director:'ผู้อำนวยการ',teacher:'ครูผู้สอน',academic_head:'หัวหน้าวิชาการ',plan_head:'หัวหน้าแผนงาน',finance:'การเงิน',admin_sec:'ธุรการ',pending:'รออนุมัติสิทธิ์'};
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const money=n=>Number(n||0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});
export const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export function grade(n){n=Number(n);return n>=80?'4':n>=75?'3.5':n>=70?'3':n>=65?'2.5':n>=60?'2':n>=55?'1.5':n>=50?'1':'0'}
export function csvCell(v){let s=String(v??'');if(/^[\s]*[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
export function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;const s=text.replace(/^\uFEFF/,'');for(let i=0;i<s.length;i++){const c=s[i];if(c==='"'){if(quoted&&s[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&s[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('รูปแบบ CSV ไม่สมบูรณ์: ปิดเครื่องหมายคำพูดไม่ครบ');row.push(cell);if(row.some(Boolean))rows.push(row);return rows}
export function validateData(kind,d){if(kind==='Students'&&(!d.student_id||!d.first_name||!d.class_level))throw Error('กรุณากรอกรหัส ชื่อ และระดับชั้นของนักเรียน');if(kind==='Teachers'&&(!d.teacher_id||!d.first_name))throw Error('กรุณากรอกรหัสและชื่อครู');if(kind==='Projects'&&(!d.name||Number(d.budget_alloc||0)<0||Number(d.budget_activity||0)<0))throw Error('กรุณากรอกชื่อโครงการและงบประมาณที่ไม่ติดลบ');if(kind==='Scores'){const n=Number(d.total);if(d.total===''||!Number.isFinite(n)||n<0||n>100)throw Error('คะแนนรวมต้องอยู่ระหว่าง 0–100');d.grade=grade(n)}if(d.birthdate&&d.birthdate>today())throw Error('วันเกิดต้องไม่อยู่ในอนาคต');if(d.citizen_id&&!/^\d{13}$/.test(d.citizen_id))throw Error('เลขประจำตัวประชาชนต้องเป็นตัวเลข 13 หลัก');for(const k of ['amount','amount_request','budget_alloc','budget_activity','weight','height','price','qty','current_stock','min_stock','max_stock','copies_total','copies_available']){if(d[k]!==undefined&&d[k]!==''&&(!Number.isFinite(Number(d[k]))||Number(d[k])<0))throw Error('จำนวนเงิน / จำนวนต้องเป็นตัวเลขที่ไม่ติดลบ')}if(d.weight&&d.height)d.bmi=(Number(d.weight)/(Number(d.height)/100)**2).toFixed(2);return d}
export function isPublicKey(key){if(key.startsWith('sb_publishable_'))return true;try{const p=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));return p.role==='anon'}catch{return false}}
export function validConfig(c){return /^https:\/\/[a-z0-9]+\.supabase\.co$/.test(c?.supabaseUrl||'')&&isPublicKey(c?.supabaseAnonKey||'')}
export function canWrite(role,kind){if(['ProjRequests','ProjExpenses','Savings','SupplyLots','SupplyTransactions','BookLoans','AssetLoans'].includes(kind))return false;if(['admin','director'].includes(role))return true;if(['Projects','ProjActivities'].includes(kind))return role==='plan_head';if(['Teachers','Classrooms','Events','Documents','DocRecipients','Books'].includes(kind))return role==='admin_sec';if(['Subjects','Assignments','Timetable','Supervision','SARContent'].includes(kind))return role==='academic_head';if(['PurchaseRequests','PurchaseOrders','ReceivingReports','Assets','AssetAudits','AssetAuditItems','AssetDisposals','Supplies'].includes(kind))return ['finance','admin_sec'].includes(role);if(['Students','Attendance','Scores','ScoreStruct','Competency','StudentAnalysis','SDQ','LD','EQAssessment','Fitness','DailyCheck','HealthCheck','GrowthRecord','Conduct'].includes(kind))return ['teacher','academic_head'].includes(role);return !['pending',null,undefined].includes(role)}
